package net.hivel.islandsrpg.weapon;
import net.hivel.islandsrpg.IslandsRPGPlugin; import net.hivel.islandsrpg.util.*; import org.bukkit.*; import org.bukkit.configuration.file.FileConfiguration; import org.bukkit.inventory.ItemStack; import org.bukkit.persistence.PersistentDataType; import java.util.*;
public class WeaponService { private final IslandsRPGPlugin plugin; private final Map<String,WeaponDefinition> weapons=new LinkedHashMap<>(); public WeaponService(IslandsRPGPlugin p){plugin=p;} public void reload(){FileConfiguration c=ConfigUtil.load(plugin,"weapons.yml"); weapons.clear(); var sec=c.getConfigurationSection("weapons"); if(sec==null)return; for(String id:sec.getKeys(false)){try{String p="weapons."+id+"."; Material m=Material.matchMaterial(c.getString(p+"material","STONE")); if(m==null){plugin.getLogger().warning("Invalid weapon material "+id);continue;} Particle hp=parseParticle(c.getString(p+"particles.held.particle","CRIT")); Particle hitp=parseParticle(c.getString(p+"particles.hit.particle","CRIT")); Sound sound=parseSound(c.getString(p+"sound.hit",null)); weapons.put(id,new WeaponDefinition(id,m,WeaponType.valueOf(c.getString(p+"type","SWORD")),c.getString(p+"display-name",id),Rarity.valueOf(c.getString(p+"rarity","COMMON")),c.getInt(p+"required-level",1),c.getDouble(p+"damage",1),c.getDouble(p+"melee-scaling",0),c.getDouble(p+"sword-scaling",0),c.getDouble(p+"magic-scaling",0),c.getBoolean(p+"glow",false),c.getBoolean(p+"unbreakable",true),c.getStringList(p+"lore"),c.getBoolean(p+"particles.held.enabled",false),hp,c.getInt(p+"particles.held.count",5),c.getInt(p+"particles.held.interval-ticks",10),c.getDouble(p+"particles.held.radius",.5),c.getBoolean(p+"particles.held.java-only",true),c.getBoolean(p+"particles.hit.enabled",false),hitp,c.getInt(p+"particles.hit.count",8),c.getBoolean(p+"particles.hit.java-only",true),sound,c.getString(p+"passive.type",""),c.getDouble(p+"passive.chance",0),c.getDouble(p+"passive.amount",0),c.getDouble(p+"passive.magic-scaling",0)));}catch(Exception e){plugin.getLogger().warning("Invalid weapon "+id+": "+e.getMessage());}}} private Particle parseParticle(String s){try{return Particle.valueOf(s);}catch(Exception e){return Particle.CRIT;}} private Sound parseSound(String s){try{return s==null?null:Sound.valueOf(s);}catch(Exception e){return null;}} public Collection<WeaponDefinition> all(){return weapons.values();} public WeaponDefinition get(String id){return weapons.get(id);} public ItemStack item(String id){WeaponDefinition w=get(id); if(w==null)return null; return new ItemBuilder(w.material()).name(w.displayName()).lore(w.lore()).glow(w.glow()).unbreakable(w.unbreakable()).pdc(plugin,"weapon_id",id).build();} public WeaponDefinition from(ItemStack item){ if(item==null||!item.hasItemMeta())return null; String id=item.getItemMeta().getPersistentDataContainer().get(plugin.key("weapon_id"), PersistentDataType.STRING); return id==null?null:get(id);} }
